package com.trampolim.api.privacy;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import java.util.*;
import java.time.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.*;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.web.context.WebApplicationContext;
import org.springframework.test.web.servlet.*;
import org.springframework.test.web.servlet.setup.MockMvcBuilders;
import org.springframework.security.test.web.servlet.setup.SecurityMockMvcConfigurers;
import org.springframework.http.MediaType;
import org.springframework.web.server.ResponseStatusException;
import com.trampolim.api.BackendApplication;
import com.trampolim.api.security.TrailTokenService;
@SpringBootTest(classes=BackendApplication.class)
class PrivacyPostgresTest {
 @Autowired @Qualifier("jdbcTemplate")JdbcTemplate opp;
 @Autowired @Qualifier("empresasJdbcTemplate")JdbcTemplate emp;
 @Autowired @Qualifier("capacitaJdbcTemplate")JdbcTemplate cap;
 @Autowired @Qualifier("opportunitiesPrivacy")PrivacyStore opportunities;
 @Autowired @Qualifier("companiesPrivacy")PrivacyStore companies;
 @Autowired @Qualifier("learningPrivacy")PrivacyStore learning;
 @Autowired TrailTokenService tokens;@Autowired PasswordEncoder passwords;@Autowired WebApplicationContext context;
 private record Person(long id,String email,String table,JdbcTemplate db,PrivacyStore store,TrailTokenService.Trail trail){}
 private Person person(int trail){return person(trail,"privacy-"+UUID.randomUUID()+"@example.test");}
 private Person person(int index,String email){JdbcTemplate db=List.of(opp,emp,cap).get(index);String table=List.of("app_users","company_users","student_users").get(index);String fields=index==2?",education_stage,terms_accepted_at":"",values=index==2?",'HIGH_SCHOOL',CURRENT_TIMESTAMP":"";long id=db.queryForObject("INSERT INTO "+table+"(email,full_name,password_hash,email_verified"+fields+") VALUES (?,'Pessoa sintética',?,TRUE"+values+") RETURNING id",Long.class,email,passwords.encode("SyntheticPassword!"));if(index>0)db.update("UPDATE "+table+" SET account_status='ACTIVE' WHERE id=?",id);return new Person(id,email,table,db,List.of(opportunities,companies,learning).get(index),TrailTokenService.Trail.values()[index]);}
 private String token(Person p){return tokens.issue(p.trail(),p.email(),p.id(),0);}
 private String path(int index){return List.of("/api/profile/privacy","/api/empresas/account/privacy","/api/capacita/account/privacy").get(index);}
 private MockMvc mvc(){return MockMvcBuilders.webAppContextSetup(context).apply(SecurityMockMvcConfigurers.springSecurity()).build();}
 private UUID id(Map<String,Object> row){return (UUID)row.get("id");}
 private PrivacyStore.Review review(String state,long revision){return new PrivacyStore.Review(state,state.equals("RETAINED")?"RETENTION_REVIEW":"USER_REQUEST","PRV_123",Instant.now().plusSeconds(86400),revision);}
 @Test void requestsAreIdempotentAndIndependentEvenWithSameEmail(){String email="shared-"+UUID.randomUUID()+"@example.test";for(int i=0;i<3;i++){var p=person(i,email);UUID key=UUID.randomUUID();var a=p.store().request(email,key,true);var b=p.store().request(email,key,true);var c=p.store().request(email,UUID.randomUUID(),true);assertEquals(id(a),id(b));assertEquals(id(a),id(c));assertEquals(1,p.store().list(email,0).size());assertEquals(1,p.db().queryForObject("SELECT count(*) FROM privacy_audit WHERE request_id=?",Integer.class,id(a)));assertNotNull(p.db().queryForObject("SELECT id FROM "+p.table()+" WHERE id=?",Long.class,p.id()));}}
 @Test void cancellationCannotAccessAnotherAccount(){var owner=person(0);var other=person(0);UUID request=id(owner.store().request(owner.email(),UUID.randomUUID(),true));var error=assertThrows(ResponseStatusException.class,()->other.store().cancel(other.email(),request,0));assertEquals(404,error.getStatusCode().value());assertTrue(other.store().list(other.email(),0).isEmpty());assertEquals("CANCELLED",owner.store().cancel(owner.email(),request,0).get("state"));}
 @Test void activeReviewCannotBeBypassedByCancellationOrDirectAccountDeletion(){for(int i=0;i<3;i++){var p=person(i);UUID request=id(p.store().request(p.email(),UUID.randomUUID(),true));p.store().review(request,review("RETAINED",0),"platform-user:1");assertEquals(409,assertThrows(ResponseStatusException.class,()->p.store().cancel(p.email(),request,1)).getStatusCode().value());assertThrows(org.springframework.dao.DataIntegrityViolationException.class,()->p.db().update("DELETE FROM "+p.table()+" WHERE id=?",p.id()));assertEquals(1,p.db().queryForObject("SELECT count(*) FROM "+p.table()+" WHERE id=?",Integer.class,p.id()));}}
 @Test void releaseAllowsExplicitDeletionAndMinimizesRemainingTrace(){for(int i=0;i<3;i++){var p=person(i);UUID request=id(p.store().request(p.email(),UUID.randomUUID(),true));p.store().review(request,review("RETAINED",0),"platform-user:1");p.store().review(request,review("READY",1),"platform-user:1");assertEquals(1,p.db().queryForObject("SELECT count(*) FROM "+p.table()+" WHERE id=?",Integer.class,p.id()));p.db().update("DELETE FROM "+p.table()+" WHERE id=?",p.id());assertNull(p.db().queryForObject("SELECT user_id FROM privacy_requests WHERE id=?",Long.class,request));assertEquals("COMPLETED",p.db().queryForObject("SELECT state FROM privacy_requests WHERE id=?",String.class,request));assertEquals(0,p.db().queryForObject("SELECT count(*) FROM privacy_audit WHERE request_id=? AND actor_ref LIKE 'holder:%'",Integer.class,request));assertEquals(1,p.db().queryForObject("SELECT count(*) FROM privacy_audit WHERE request_id=? AND event='ACCOUNT_DELETED'",Integer.class,request));}}
 @Test void staleReviewAndInventedCompletionAreRejected(){var p=person(0);UUID request=id(p.store().request(p.email(),UUID.randomUUID(),true));p.store().review(request,review("REVIEWING",0),"platform-user:1");assertEquals(409,assertThrows(ResponseStatusException.class,()->p.store().review(request,review("READY",0),"platform-user:1")).getStatusCode().value());assertEquals(400,assertThrows(ResponseStatusException.class,()->p.store().review(request,review("COMPLETED",1),"platform-user:1")).getStatusCode().value());}
 @Test void retentionNeedsReasonAndReviewDateWithoutCollectingSensitiveText(){var p=person(2);UUID request=id(p.store().request(p.email(),UUID.randomUUID(),true));for(var input:List.of(new PrivacyStore.Review("RETAINED","USER_REQUEST","PRV_123",Instant.now().plusSeconds(100),0),new PrivacyStore.Review("RETAINED","RETENTION_REVIEW","PRV_123",null,0),new PrivacyStore.Review("RETAINED","RETENTION_REVIEW","Nome e diagnóstico",Instant.now().plusSeconds(100),0)))assertEquals(400,assertThrows(ResponseStatusException.class,()->p.store().review(request,input,"platform-user:1")).getStatusCode().value());}
 @Test void concurrentDuplicateRequestsProduceOneActiveProtocol()throws Exception{var p=person(1);try(var executor=Executors.newFixedThreadPool(2)){var a=executor.submit(()->p.store().request(p.email(),UUID.randomUUID(),true));var b=executor.submit(()->p.store().request(p.email(),UUID.randomUUID(),true));assertEquals(id(a.get(15,TimeUnit.SECONDS)),id(b.get(15,TimeUnit.SECONDS)));}assertEquals(1,p.store().list(p.email(),0).size());}
 @Test void tokensCannotCrossTrailRoutesAndOrdinaryAccountsCannotReview()throws Exception{var mvc=mvc();for(int i=0;i<3;i++){var p=person(i);mvc.perform(get(path(i)+"/requests").header("Authorization","Bearer "+token(p))).andExpect(status().isOk()).andExpect(header().string("Cache-Control","private, no-store, max-age=0"));for(int j=0;j<3;j++)if(j!=i){int status=mvc.perform(get(path(j)+"/requests").header("Authorization","Bearer "+token(p))).andReturn().getResponse().getStatus();assertTrue(Set.of(401,403).contains(status));}assertNotEquals(200,mvc.perform(get("/api/admin/privacy/capacita/requests").header("Authorization","Bearer "+token(p))).andReturn().getResponse().getStatus());}}
 @Test void authenticatedHolderCanSubmitWithoutAutomaticErasure()throws Exception{var p=person(2);mvc().perform(post(path(2)+"/requests").header("Authorization","Bearer "+token(p)).contentType(MediaType.APPLICATION_JSON).content("{\"confirmed\":true,\"clientKey\":\""+UUID.randomUUID()+"\"}")).andExpect(status().isOk()).andExpect(jsonPath("$.state").value("OPEN"));assertEquals(1,p.db().queryForObject("SELECT count(*) FROM student_users WHERE id=?",Integer.class,p.id()));}
 @Test void onlyPlatformAdministratorsCanReviewAndAudit()throws Exception{var admin=person(0);opp.update("INSERT INTO platform_roles(user_id,role) VALUES (?,'SUPER_ADMIN')",admin.id());var owner=person(2);UUID request=id(owner.store().request(owner.email(),UUID.randomUUID(),true));mvc().perform(put("/api/admin/privacy/capacita/requests/"+request).header("Authorization","Bearer "+token(admin)).contentType(MediaType.APPLICATION_JSON).content("{\"state\":\"REVIEWING\",\"basisCode\":\"SECURITY_REVIEW\",\"caseReference\":\"PRV_TEST\",\"expectedRevision\":0}")).andExpect(status().isOk()).andExpect(jsonPath("$.state").value("REVIEWING"));mvc().perform(get("/api/admin/privacy/capacita/requests/"+request+"/audit").header("Authorization","Bearer "+token(admin))).andExpect(status().isOk()).andExpect(jsonPath("$[0].actor_ref").value("platform-user:"+admin.id()));}
 @Test void exportIsNoStoreAuditedAndDoesNotRevealCredentialsOrOtherAccounts()throws Exception{var p=person(1);var other=person(1);var response=mvc().perform(get("/api/empresas/account/export").header("Authorization","Bearer "+token(p))).andExpect(status().isOk()).andExpect(header().string("Cache-Control","private, no-store, max-age=0")).andReturn().getResponse().getContentAsString();assertFalse(response.contains(other.email()));assertFalse(response.contains("password_hash"));assertFalse(response.contains("SyntheticPassword"));assertEquals(1,emp.queryForObject("SELECT count(*) FROM privacy_export_audit WHERE user_id=?",Integer.class,p.id()));}
 @Test void teachingExportIsPaginatedAndContainsOnlyOwnMaterials()throws Exception{var p=person(2);var other=person(2);for(var teacher:List.of(p,other))cap.update("INSERT INTO learning_courses(teacher_id,title,category) VALUES (?,?,'Teste')",teacher.id(),"Curso de "+teacher.id());var body=mvc().perform(get("/api/capacita/account/export/teaching").header("Authorization","Bearer "+token(p))).andExpect(status().isOk()).andExpect(jsonPath("$.items.length()").value(1)).andReturn().getResponse().getContentAsString();assertTrue(body.contains("Curso de "+p.id()));assertFalse(body.contains("Curso de "+other.id()));assertFalse(body.contains("password"));}
 @Test void legacySelfDeletionIsBlockedWithSanitizedConflictWhileRetained()throws Exception{var p=person(2);UUID request=id(p.store().request(p.email(),UUID.randomUUID(),true));p.store().review(request,review("RETAINED",0),"platform-user:1");mvc().perform(delete("/api/capacita/account").header("Authorization","Bearer "+token(p)).contentType(MediaType.APPLICATION_JSON).content("{\"password\":\"SyntheticPassword!\"}")).andExpect(status().isConflict()).andExpect(jsonPath("$.detail").value("Sua solicitação está em análise ou retenção. Consulte o protocolo de privacidade antes de excluir a conta."));}
 @Test void disposalPreviewNeverDeletesAndExcludesActiveRequests(){var p=person(0);UUID closed=id(p.store().request(p.email(),UUID.randomUUID(),true));p.store().cancel(p.email(),closed,0);opp.update("UPDATE privacy_requests SET updated_at=CURRENT_TIMESTAMP-INTERVAL '800 days' WHERE id=?",closed);UUID active=id(p.store().request(p.email(),UUID.randomUUID(),true));opp.update("UPDATE privacy_requests SET updated_at=CURRENT_TIMESTAMP-INTERVAL '800 days' WHERE id=?",active);var preview=p.store().disposalPreview(730);assertEquals(false,preview.get("automaticDisposal"));assertTrue(((Number)preview.get("closedRequestCandidates")).longValue()>=1);assertEquals(2,opp.queryForObject("SELECT count(*) FROM privacy_requests WHERE user_id=?",Integer.class,p.id()));assertEquals("OPEN",opp.queryForObject("SELECT state FROM privacy_requests WHERE id=?",String.class,active));assertThrows(ResponseStatusException.class,()->p.store().disposalPreview(0));}
}
